CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, phone VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, password_hash TEXT NOT NULL, onboarding_completed BOOLEAN NOT NULL DEFAULT FALSE, level VARCHAR(120), subjects JSONB, goal TEXT, learning_style VARCHAR(120), difficulties TEXT, welcome_seen BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(40) PRIMARY KEY, name VARCHAR(120) NOT NULL, monthly_price NUMERIC(12,2) NOT NULL, annual_price NUMERIC(12,2) NOT NULL, documents_limit INTEGER NOT NULL, daily_requests INTEGER NOT NULL, features JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, original_filename TEXT NOT NULL, storage_path TEXT NOT NULL, mime_type VARCHAR(120) NOT NULL, size_bytes BIGINT NOT NULL, content_hash CHAR(64), status VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS document_chunks (id UUID PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, content TEXT NOT NULL, metadata JSONB, created_at TIMESTAMPTZ NOT NULL, UNIQUE(document_id, chunk_index));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, document_ids JSONB NOT NULL DEFAULT '[]'::jsonb);
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS document_ids JSONB NOT NULL DEFAULT '[]'::jsonb;
CREATE TABLE IF NOT EXISTS messages (id UUID PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role VARCHAR(16) NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS memories (id UUID PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, memory_type VARCHAR(40) NOT NULL, memory_key VARCHAR(120) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id,memory_key));
CREATE TABLE IF NOT EXISTS sessions (id UUID PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS subscriptions (id UUID PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, plan_id VARCHAR(40) NOT NULL REFERENCES plans(id) ON DELETE RESTRICT, status VARCHAR(32) NOT NULL, billing_cycle VARCHAR(16) NOT NULL, started_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ, last_transaction_id VARCHAR(120));
CREATE TABLE IF NOT EXISTS payments (transaction_id VARCHAR(120) PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, plan_id VARCHAR(40) NOT NULL REFERENCES plans(id) ON DELETE RESTRICT, billing_cycle VARCHAR(16) NOT NULL, amount NUMERIC(12,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, simulation BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS daily_usage (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, usage_date DATE NOT NULL, ai_requests INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,usage_date));
CREATE INDEX IF NOT EXISTS idx_documents_user ON documents(user_id); CREATE INDEX IF NOT EXISTS idx_conversations_user ON conversations(user_id); CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id); CREATE INDEX IF NOT EXISTS idx_memories_user ON memories(user_id);
